  "verdict": "PASS",
  "checks": [
    {
      "id": "RISK-APPROPRIATE",
      "result": "PASS",
      "severity": "Major",
      "finding": "tasks.md T-001–T-009 correctly classify CI evidence contracts, model identity/selection contracts, protected launch integration and notification controls as high risk. T-010 is bounded to controlled evaluation and adoption metadata; T-011 publishes verified activation references, documentation and immutable release metadata without changing the underlying algorithms. Their medium classifications are consistent with these bounded scopes."
    },
    {
      "id": "HIGH-CRITICAL-EVIDENCE",
      "result": "PASS",
      "severity": "Critical",
      "finding": "Every high-risk task, T-001–T-009, explicitly requires in Done When failing tests committed before implementation, captured Red→Green evidence, a named independent reviewer verdict and a formal quality-gate result. No critical-risk task is declared."
    },
    {
      "id": "TASK-SIZE",
      "result": "PASS",
      "severity": "Major",
      "finding": "tasks.md separates planning, aggregation and workflow integration into T-001–T-003; discovery, binding, selection, transport and installed entries into T-004–T-008; and maintenance, adoption and release into T-009–T-011. Each task has six grouped completion criteria and explicit ownership exclusions. Renderer/install/entry work in T-008 forms one integration concern rather than fragmented file edits."
    },
    {
      "id": "EDGE-CASE-COVERAGE",
      "result": "PASS",
      "severity": "Major",
      "finding": "acceptance-tests.md covers planner invalid identities and omissions through AC-001–AC-003; aggregation failures through AC-005; discovery failures through AC-012; configuration, eligibility and budget rejection through AC-013/AC-014/AC-016; resume/reroute failures through AC-015/AC-016; maintenance failures through AC-017; and stale/comment-only/native-precedence integration through AC-018 and TEST-120/161. tasks.md assigns these branches to their functional owners. T-010 additionally requires failed candidates to remain unadopted with retained results."
    },
    {
      "id": "TEST-TYPE-MATCH",
      "result": "PASS",
      "severity": "Major",
      "finding": "tasks.md distinguishes component fixtures from integration and native execution: T-003 checks workflow/planner/aggregate integration, T-007 checks selector-to-transport behavior, and T-008 checks renderer/installer/installed-entry integration. T-010's controlled acceptance evaluation cites AC-013/AC-019 and TEST-103/104/127; T-011 separates hosted acceptance from local fixtures. No test scope is incorrectly presented as unit or end-to-end coverage."
    },
    {
      "id": "ROLLBACK-PLAN",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-001–T-009 each require documented and tested disposable-checkout rollback with before/after hashes and baseline results. tasks.md Shared file ordering and rollback further specifies task-owned restoration, CI force-full recovery, validated model pinning or prior tested release, and preservation of identity ledgers and frozen history; infra-spec.md corroborates these recovery paths."
    },
    {
      "id": "SCOPE-DISJOINT",
      "result": "PASS",
      "severity": "Major",
      "finding": "tasks.md serializes shared catalog/helper edits and assigns distinct purposes: T-001 planning, T-002 evidence aggregation, T-003 wiring; T-004 discovery, T-005 binding, T-006 resolution, T-007 transport. T-008 consumes transport rather than reimplementing it. T-010's policy/adoption edits follow T-006 transitively; T-011's activation references follow implementation. Independent T-009/T-010 own different write surfaces."
    },
    {
      "id": "DEPENDENCY-OVERLAP",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-002 consumes T-001 plans; T-003 consumes the passed producer/verifier; T-005 consumes T-004 observations; T-006 consumes binding validators; T-007 consumes selection; T-008 consumes transports; T-009 consumes policy; T-010 consumes installed entries; T-011 joins maintenance and adoption. T-004's ordering after T-003 implements requirements.md Overview's explicit CI-first/model-second constraint. No unnecessary dependency is introduced between T-009 and T-010."
    },
    {
      "id": "BUGFIX-DIAGNOSTIC-PATH",
      "result": "SKIP",
      "severity": "Major",
      "finding": "SKIP: no bugfix or debugging task in scope."
    }
